safe_repair.postcondition:
And(
  Length(ret) == Length(a),
  ForAll([i], Implies(And(0 <= i, i < Length(a)),
    And(
      0 <= ret[i],
      ret[i] <= 1,
      Exists([min_val, max_val],
        And(
          min_val == a[0],
          max_val == a[0],
          ForAll([j], Implies(And(0 <= j, j < Length(a)),
            And(min_val <= a[j], a[j] <= max_val)
          )),
          (max_val != min_val) Implies (ret[i] == (a[i] - min_val) / (max_val - min_val)),
          (max_val == min_val) Implies (ret[i] == 0.0)
        )
      )
    )
  ))
)
